// When the user clicks on the search box, we want to toggle the search dropdown
function displayToggleSearch(e) {
  e.preventDefault();
  e.stopPropagation();

  closeDropdownSearch(e);
  
  if (idx === null) {
    console.log("Building search index...");
    prepareIdxAndDocMap();
    console.log("Search index built.");
  }
  const dropdown = document.querySelector("#search-dropdown-content");
  if (dropdown) {
    if (!dropdown.classList.contains("show")) {
      dropdown.classList.add("show");
    }
    document.addEventListener("click", closeDropdownSearch);
    document.addEventListener("keydown", searchOnKeyDown);
    document.addEventListener("keyup", searchOnKeyUp);
  }
}

//We want to prepare the index only after clicking the search bar
var idx = null
const docMap = new Map()

function prepareIdxAndDocMap() {
  const docs = [  
    {
      "title": "Alignment",
      "url": "/dixtra/docs/reference/alignment.html",
      "content": "Alignment What lines up in columns. Every setting is in the settings table. Only adjacent one-line items align: a blank line, an item over several lines or any other statement ends a group of aligned items (see also alignment.across-comments). An item that would not fit once aligned breaks instead, and the items before and after it align separately. alignment.assignment-groups The groups of keywords whose adjacent one-line definitions align their =. The keywords are val, lazy-val, var, def, given-alias and type-def. A keyword is in at most one group, and a keyword in no group never aligns and ends the groups around it. Default alignment.assignment-groups = [[val, lazy-val, var, def]]. With the default: val name = \"dixtra\" var count = 0 def totalCount = count * 2 With alignment.assignment-groups = [[val, var], [def]], the def aligns with neither: val name = \"dixtra\" var count = 0 def totalCount = count * 2 With alignment.assignment-groups = [[val, def]], the var aligns with nothing, and the definitions before and after it align separately: val name = \"dixtra\" var count = 0 val totalCount = count * 2 def f = 1 With alignment.assignment-groups = [], no definition aligns. alignment.operators The operators that align column by column. Default alignment.operators = [\"=\", \"+=\", \"-=\", \"*=\", \"/=\", \":=\", \"++=\", \"%\", \"%%\", \"%%%\"]. They align in adjacent one-line statements, in adjacent one-line elements of a list laid out one per line, and in an operation that is the only argument of a call statement. The named arguments follow alignment.named-arguments instead. total += x n = 0 Seq( \"org.typelevel\" %% \"cats-core\" % \"2.13.0\", \"co.fs2\" %% \"fs2-io\" % \"3.13.0\", ) With alignment.operators = [], no operator aligns. alignment.arrows.cases Whether the =&gt; of adjacent one-line cases align. Default alignment.arrows.cases = true. case Some(value) =&gt; value case None =&gt; default With alignment.arrows.cases = false: case Some(value) =&gt; value case None =&gt; default alignment.arrows.pairs Whether the -&gt; of the a -&gt; b elements of a list laid out one per line align. Default alignment.arrows.pairs = true. Map( \"one\" -&gt; 1, \"three\" -&gt; 3, ) With alignment.arrows.pairs = false: Map( \"one\" -&gt; 1, \"three\" -&gt; 3, ) alignment.arrows.for-enumerators Whether the &lt;- and the = of the enumerators of a for align. Default alignment.arrows.for-enumerators = true. for user &lt;- users userCount = users.size account &lt;- accounts(user) yield account With alignment.arrows.for-enumerators = false: for user &lt;- users userCount = users.size account &lt;- accounts(user) yield account alignment.extends-clauses Whether the extends of adjacent one-line definitions (classes, objects, traits, enum cases) align. Default alignment.extends-clauses = true. case Red extends Color(\"red\") case Green extends Color(\"green\") With alignment.extends-clauses = false: case Red extends Color(\"red\") case Green extends Color(\"green\") alignment.named-arguments Whether the = of adjacent one-line named arguments align, in a call laid out one argument per line. Default alignment.named-arguments = false. With alignment.named-arguments = true: MyCaseClass( aaa = \"\", name = 123, ) With alignment.named-arguments = false: MyCaseClass( aaa = \"\", name = 123, ) alignment.trailing-comments Whether the comments at the end of consecutive lines of code start on one column, one space after the longest code. A line without a trailing comment ends the group. Default alignment.trailing-comments = false. With alignment.trailing-comments = true: run(1) // one compute(2) // two With alignment.trailing-comments = false: run(1) // one compute(2) // two alignment.across-comments Whether a comment on its own line between two items keeps them in one group. The items are definitions, statements, cases and list elements. A blank line still ends a group, and the enumerators of a for always align across comments. Default alignment.across-comments = false. With alignment.across-comments = true, one group: val a = 1 // note val bbb = 2 With alignment.across-comments = false, two groups: val a = 1 // note val bbb = 2 alignment.scaladoc.tags Whether the descriptions of the tags of a scaladoc start on one column. Wrapped description lines continue under the start of their description. Default alignment.scaladoc.tags = false. With alignment.scaladoc.tags = true: /** * @param source The source text. * @param width The maximum width. * @return The formatted text. */ With alignment.scaladoc.tags = false: /** * @param source The source text. * @param width The maximum width. * @return The formatted text. */ The settings Setting Default Values alignment.assignment-groups [[val, lazy-val, var, def]] a list of lists of keywords alignment.operators [\"=\", \"+=\", \"-=\", \"*=\", \"/=\", \":=\", \"++=\", \"%\", \"%%\", \"%%%\"] a list of operators alignment.arrows.cases true true, false alignment.arrows.pairs true true, false alignment.arrows.for-enumerators true true, false alignment.extends-clauses true true, false alignment.named-arguments false true, false alignment.trailing-comments false true, false alignment.across-comments false true, false alignment.scaladoc.tags false true, false"
    } ,    
    {
      "title": "API documentation",
      "url": "/dixtra/docs/api.html",
      "content": "API documentation The scaladoc of the two artifacts is published with the site: The formatter, dixtra-core The command line, dixtra-cli The source and the changelog are on GitHub."
    } ,    
    {
      "title": "Blank lines",
      "url": "/dixtra/docs/reference/blank-lines.html",
      "content": "Blank lines Where blank lines go, beyond the ones the author wrote between statements. Every setting is in the settings table. Some rules have no setting: A run of blank lines always becomes one. A method after another statement always gets a blank line before it, and before its annotations and comments. The blank lines between the imports are always removed, so the groups of imports are not supported. The edges of the bodies The edges are after the opening { (or after the header, without braces) and before the closing }; a body without braces has no closing edge. For package, the edge is the blank line after the package clause. blank-lines.body-edges.&lt;construct&gt; = always — a blank line at both edges: class A { def f = 1 } blank-lines.body-edges.&lt;construct&gt; = never — no blank line at the edges: class A { def f = 1 } blank-lines.body-edges.&lt;construct&gt; = keep — as written, made to agree: a blank line at either edge means one at both. Written with a blank line only after the {, the class gets one before the } too: class A { def f = 1 } By default the containers and the test blocks keep the blank lines the author wrote, the package clause is followed by one, and the other bodies never have any. blank-lines.body-edges.test-case and blank-lines.body-edges.test-group tell the tests from the groups of tests, so a configuration can give a blank line after \"a parser\" should { and none after \"parses a number\" in {: \"a parser\" should { \"parse a number\" in { parse(\"1\") } } A test case is a test block that holds no other test block; a group is one that holds them. See bodies for the difference. The blank line between two one-line definitions blank-lines.between-alignment-groups holds the blank line between two adjacent one-line definitions of different alignment groups (see alignment.assignment-groups). The examples are with alignment.assignment-groups = [[val], [def]]. blank-lines.between-alignment-groups = keep — as written. blank-lines.between-alignment-groups = always: val a = 1 def b = 2 blank-lines.between-alignment-groups = never: val a = 1 def b = 2 The blank line before a scaladoc blank-lines.before-scaladoc holds the blank line before a scaladoc that follows a line of code. blank-lines.before-scaladoc = always — before every scaladoc, except a one-line scaladoc right after a line that opens a block. With blank-lines.body-edges.class = keep, a scaladoc at the start of a class gives both edges a blank line: class Repository { /** Description here */ def read(): Int = 1 } blank-lines.before-scaladoc = always-multiline — as blank-lines.before-scaladoc = always, for a multi-line scaladoc only; a one-line scaladoc stays as written, and does not count as a blank line at the start of a body: def a = 1 /** One line */ def b = 2 blank-lines.before-scaladoc = keep — as written. blank-lines.before-scaladoc = never — no blank line, a method’s included; after a line that opens a block, blank-lines.body-edges decides: def a = 1 /** Description here */ def b = 2 At the start of a body (a class, an object, a trait, an enum, an extension, a package), a scaladoc that gets a blank line counts as a blank line written at the opening edge, and blank-lines.body-edges decides. The settings Setting Default blank-lines.body-edges.abstract-class keep blank-lines.body-edges.block-argument never blank-lines.body-edges.case-body never blank-lines.body-edges.case-class keep blank-lines.body-edges.class keep blank-lines.body-edges.def never blank-lines.body-edges.enum keep blank-lines.body-edges.extension keep blank-lines.body-edges.for never blank-lines.body-edges.for-yield never blank-lines.body-edges.given-alias never blank-lines.body-edges.given-instance keep blank-lines.body-edges.if never blank-lines.body-edges.lambda-argument never blank-lines.body-edges.lambda-body never blank-lines.body-edges.lazy-val never blank-lines.body-edges.match never blank-lines.body-edges.new-anonymous never blank-lines.body-edges.object keep blank-lines.body-edges.package always blank-lines.body-edges.package-object keep blank-lines.body-edges.test-case keep blank-lines.body-edges.test-group keep blank-lines.body-edges.trait keep blank-lines.body-edges.try never blank-lines.body-edges.val never blank-lines.body-edges.var never blank-lines.body-edges.while never blank-lines.between-alignment-groups keep blank-lines.before-scaladoc always"
    } ,    
    {
      "title": "Bodies",
      "url": "/dixtra/docs/reference/body.html",
      "content": "Bodies Where each body goes relative to the separator before it: on its line, or below it one level in. The separators are the = of a definition, the =&gt; of a lambda or of a case, the then and the else of an if/else, the do of a loop. Every setting is in the settings table. The values A construct with a single body (a definition, a lambda, a loop) takes: body.&lt;construct&gt; = keep — the body stays where the author wrote it. body.&lt;construct&gt; = always-join — the body on the line of its separator, even when the author wrote it below. body.&lt;construct&gt; = always-break — the body below its separator, even when the author wrote it on the line. body.&lt;construct&gt; = keep: def total = xs.sum body.&lt;construct&gt; = always-join: def total = xs.sum body.&lt;construct&gt; = always-break: def total = xs.sum The bodies of a construct with several of them (the branches of an if/else, the cases of a match, the bodies of a try) are treated as a group, never one by one: either every body is on the line of its separator, or every body is below it. A group where some bodies are inline and some others are on a new line is mixed. These constructs take: body.&lt;construct&gt; = join-mixed — a mixed group is joined on the lines of the separators; a group all on its lines, or all below, stays as it is. body.&lt;construct&gt; = break-mixed — a mixed group goes below the separators; a group all on its lines, or all below, stays as it is. body.&lt;construct&gt; = always-join — every body on the line of its separator. body.&lt;construct&gt; = always-break — every body below its separator. The examples are for this mixed input: if c then a else b body.&lt;construct&gt; = join-mixed — the first branch moves up: if c then a else b body.&lt;construct&gt; = break-mixed — the second branch goes below too: if c then a else b body.&lt;construct&gt; = always-join — as body.&lt;construct&gt; = join-mixed, and a group all below its separators moves up too. body.&lt;construct&gt; = always-break — as body.&lt;construct&gt; = break-mixed, and if c then a else b goes below too. A group of one body (an if without else, a match with one case) is never mixed, so both -mixed values leave it as written. The rules that hold whatever the setting A body goes below its separator when it cannot be joined on its line: it does not fit there on one line, or a comment follows the separator. In a group, such a body puts every body of the group below its separator, and so does a body that holds an if, a match or a try. The settings move bodies only relative to their separators: an else written on its own line stays on its own line, and every case is on its own line. With braces (see braces), a body below its separator is in braces, and a construct whose bodies are on their lines has none: if (c) a else b, for (x &lt;- xs) f(x), while (c) step(). The settings Setting Default The body after body.def keep The = of a def body.val keep The = of a val body.lazy-val keep The = of a lazy val body.var keep The = of a var body.given-alias keep The = of a given alias body.type-def keep The = of a type definition body.assignment keep The = of an assignment body.named-argument keep The = of a named argument body.lambda-argument keep The =&gt; of a lambda given in braces or after a colon body.lambda-body keep The =&gt; of any other lambda body.block-argument keep The { or the colon of a block given as an argument body.test-case keep The { or the colon of a test case body.test-group keep The { or the colon of a group of tests body.if break-mixed The then and the else of an if/else body.case-body break-mixed The =&gt; of the cases of a match, of a { case ... } or of a catch body.try break-mixed The try and the finally of a try body.for keep The do of a for loop body.for-yield break-complex The yield of a for-comprehension body.while keep The do of a while loop body.semicolon-statements always-break The ; between the statements of a body written on one line The body after = The eight settings of the = body — body.def, body.val, body.lazy-val, body.var, body.given-alias, body.type-def, body.assignment, body.named-argument — move the body the same way. With body.def = always-break: def total = xs.sum A def whose signature is over several lines keeps its body where it is, even with body.def = always-join. The bodies of a lambda body.lambda-argument is the =&gt; of a lambda given in braces or after a colon; body.lambda-body is the =&gt; of any other lambda. body.lambda-argument = always-join: xs.foreach { x =&gt; println(x) } body.lambda-argument = always-break: xs.foreach { x =&gt; println(x) } The blocks given as arguments body.block-argument is a block of statements given as an argument, without lambda parameters, that is not a test block. A test block is a block of statements given to a call labelled by a string. Dixtra tells two of them apart by what they hold: a body.test-case holds no other test block, as the test cases of ScalaTest, MUnit, specs2 or utest do; a body.test-group holds other test blocks among its statements, as the groups of ScalaTest’s WordSpec, FreeSpec and FunSpec, specs2 or utest do. A block given to withClue is not a test. All three settings move their statements the same way, and telling the cases from the groups lets a configuration lay out one and not the other. After an operator (\"a parser\" in { ... }, \"a parser\" should { ... }) the braces of a test block always stay, so only a call takes the braceless form. body.block-argument = always-join — the statements on the line of the {, with a ; between several of them: Resource.make { open() } body.block-argument = always-break: Resource.make { open() } The branches of an if/else body.if moves the branches after the then and the else. The branches of an else if chain are one group with those of the outer if/else. On the lines of their separators, the if/else stays on one line when the author wrote each else on the line of the branch before it; otherwise every else starts a line of its own. Below their separators, an else if stays on the line of its else. body.if = always-join, for the input above: if c then a else b body.if = always-break: if c then a else b The bodies of the cases body.case-body moves the bodies after the =&gt; of the cases of a match, of a { case ... } or of a catch, which are one group. When a case would not fit once its arrow is aligned (see alignment.arrows.cases), every body goes below its =&gt;. The examples are for this mixed input: x match { case 1 =&gt; \"one\" case 22 =&gt; \"two\" } body.case-body = join-mixed: x match { case 1 =&gt; \"one\" case 22 =&gt; \"two\" } body.case-body = break-mixed: x match { case 1 =&gt; \"one\" case 22 =&gt; \"two\" } body.case-body = always-join — as body.case-body = join-mixed, also when every body is below its =&gt;. body.case-body = always-break — as body.case-body = break-mixed, also when every body is on its =&gt; line. The bodies of a try body.try moves the bodies after the try and the finally, which are one group; the cases after catch follow body.case-body. A try written on one line that fits stays as it is, unless its bodies go below their keywords. With braces.try = force-braces, the bodies of a try over several lines are always below their {. The examples, with braces.try = force-indent, are for this mixed input: try a() finally b() body.try = join-mixed: try a() finally b() body.try = break-mixed: try a() finally b() body.try = always-join — as body.try = join-mixed, also when both bodies are below their keywords. body.try = always-break — as body.try = break-mixed, also when both bodies are on the lines of their keywords. The bodies of the loops body.for is the body after the do of a for loop; body.while is the body after the do of a while loop. A loop written on one line that fits stays as it is, unless always-break. body.for = always-join: for x &lt;- xs do println(x) body.for = always-break: for x &lt;- xs do println(x) With braces.for = force-braces, a body on its line gives for (x &lt;- xs) println(x). The expression after yield body.for-yield moves the expression after the yield of a for-comprehension. A for-comprehension written on one line that fits stays as it is, unless always-break. body.for-yield = always-join: yield x + y body.for-yield = always-break: yield x + y body.for-yield = break-complex — as body.for-yield = always-break, but a simple expression, a single name, a path (ExitCode.Success) or a literal stays on the line of the yield: yield x + y yield name The statements on one line body.semicolon-statements holds the statements of a body written on one line and separated by ;, whatever the construct. body.semicolon-statements = keep — they stay on one line, with their braces, while it fits: def this(s: String) = { this(s.toInt, 0); println(s) } body.semicolon-statements = always-break — one statement per line, below the =: def this(s: String) = this(s.toInt, 0) println(s)"
    } ,    
    {
      "title": "Braces",
      "url": "/dixtra/docs/reference/braces.html",
      "content": "Braces Whether each construct writes its body in braces, braceless with an end marker, or braceless, and where the braces go. Every setting is in the settings table; the configuration page explains how to write them. The values braces.&lt;construct&gt; = force-braces — in curly braces. braces.&lt;construct&gt; = force-end — braceless, closed by an end marker when it spans several lines. braces.&lt;construct&gt; = force-indent — braceless and without an end marker, the body only indented. braces.&lt;construct&gt; = keep — as the author wrote it. braces.&lt;construct&gt; = force-braces: class A { def f = 1 } braces.&lt;construct&gt; = force-end: class A: def f = 1 end A braces.&lt;construct&gt; = force-indent: class A: def f = 1 braces.&lt;construct&gt; = keep: the construct stays as it is written. block-argument, case-body, lambda-argument, lambda-body, test-case and test-group have no end marker, so they reject braces.&lt;construct&gt; = force-end. A for, a while or an if written on one line that fits stays as it is, and a case class or an object without a body never gets braces. braces.style Where the braces go relative to the code around them. Default braces.style = 1tbs. It applies to every brace Dixtra writes; the braces of an argument (xs.map { x =&gt; ... }) and of a body after =&gt; stay where they are. See Indentation Style braces.style = 1tbs — the { at the end of the header line, and } else { on one line: if (c) { a() } else { b() } braces.style = stroustrup — as braces.style = 1tbs, with else, catch, finally and yield starting the line after the closing }: if (c) { a() } else { b() } braces.style = allman — as braces.style = stroustrup, with every opening { of a body on its own line: if (c) { a() } else { b() } braces.imports Whether the single selector of an import or of an export is in braces. Default braces.imports = keep. The selectors keep their spelling (_ / *, =&gt; / as), and an import with several selectors always keeps its braces. braces.imports = force-braces: import a.{ B } import a.{ * } braces.imports = avoid-braces — a rename keeps its braces: import a.B import a.* import a.{ B =&gt; C } braces.imports = keep: as written. The settings Setting Default braces.style 1tbs braces.imports keep braces.abstract-class force-braces braces.block-argument force-braces braces.case-body force-indent braces.case-class force-braces braces.class force-braces braces.def force-indent braces.enum force-braces braces.extension force-braces braces.for force-indent braces.for-yield force-indent braces.given-alias keep braces.given-instance force-braces braces.if force-indent braces.lambda-argument force-braces braces.lambda-body keep braces.lazy-val force-indent braces.match force-braces braces.new-anonymous force-braces braces.object force-braces braces.package force-indent braces.package-object keep braces.test-case force-braces braces.test-group force-braces braces.trait force-braces braces.try force-braces braces.val force-indent braces.var force-indent braces.while force-braces braces.single-expr.case-body force-indent braces.single-expr.def force-indent braces.single-expr.given-alias force-indent braces.single-expr.lambda-body force-indent braces.single-expr.lazy-val force-indent braces.single-expr.val force-indent braces.single-expr.var force-indent braces.single-expr holds the braces around a body that is a single expression, after the = of a definition or the =&gt; of a lambda or of a case; a body of several statements follows the setting of its construct above. braces.&lt;construct&gt; = force-braces puts a body over several lines in braces (a body on one line never gets them), braces.&lt;construct&gt; = force-indent removes them, braces.&lt;construct&gt; = keep leaves them as written; braces.&lt;construct&gt; = force-end is rejected. Each construct in the form its default does not write // braces.abstract-class = force-indent abstract class A: def f: Int // braces.block-argument = force-indent Resource.make: open() // braces.case-body = force-braces case p =&gt; { a() b() } // braces.case-class = force-indent case class A(x: Int): def f = x // braces.class = force-indent class A: def f = 1 // braces.def = force-braces def f = { val a = 1 a + 1 } // braces.enum = force-indent enum Color: case Red case Green // braces.extension = force-indent extension (s: String) def a = s def b = s // braces.for = force-braces for { x &lt;- xs } { a(x) } // braces.for-yield = force-braces for { x &lt;- xs y &lt;- ys } yield { x + y } // braces.given-alias = force-braces given Ord[Int] = { val b = 1 ord(b) } // braces.given-instance = force-indent given Ord[Int] with def compare(a: Int, b: Int) = a - b // braces.if = force-braces if (c) { a() } else { b() } // braces.lambda-argument = force-indent xs.map: x =&gt; x + 1 // braces.lambda-body = force-braces val f = (x: Int) =&gt; { val y = x y + 1 } // braces.lazy-val = force-braces lazy val a = { val b = 1 b + 1 } // braces.match = force-indent x match case 1 =&gt; a case 2 =&gt; b // braces.new-anonymous = force-indent new Runnable: def run() = () // braces.object = force-indent object A: val a = 1 // braces.package = force-braces package a.b { object C } // braces.package-object = force-braces package object a { val x = 1 } // braces.test-case = force-indent test(\"a parser\"): parse(\"1\") // braces.test-group = force-indent describe(\"a parser\"): it(\"parses a number\") { parse(\"1\") } // braces.trait = force-indent trait A: def f: Int // braces.try = force-indent try a() finally b() // braces.val = force-braces val a = { val b = 1 b + 1 } // braces.var = force-braces var a = { val b = 1 b + 1 } // braces.while = force-indent while c do step() more() // braces.single-expr.def = keep def f: Int =&gt; Int = { x =&gt; val y = x y + 1 }"
    } ,    
    {
      "title": "Building from source",
      "url": "/dixtra/docs/building.html",
      "content": "Building from source The build needs sbt 2.0 and a JDK that sbt 2 supports (17 or later). It has five projects: Project Artifact Contents dixtra-core/ dixtra-core the formatter (Scala 3.9) dixtra-cli/ dixtra-cli the command line, the configuration files, reference.conf dixtra-sbt/ sbt-dixtra the sbt plugin dixtra-vscode/ dixtra-vscode the VS Code extension dixtra-bench/ not published the JMH benchmarks of the formatter sbt publishLocal # publish the three artifacts to the local Ivy repository sbt test # the tests of the formatter and the command line sbt sbtDixtra/scripted # the tests of the plugin sbt \"run --check dixtra-core/src\" # the command line from the build The sbt plugin To build and deploy the sbt plugin locally, run: sbt publishLocal and the artifacts will be published under &lt;local_ivy2&gt;/local/com.colofabrix.scala. The command line tool sbt dixtraCli/nativeImage builds the command line with GraalVM native-image, into target/out/jvm/scala-3.9.0/dixtra-cli/native/dixtra (dixtra.exe on Windows). Requirements: GRAALVM_HOME pointing to a GraalVM installation (GraalVM Community 25 or later); on Windows, the Visual Studio C++ build tools (the “Desktop development with C++” workload). If native-image doesn’t find them, start sbt from an “x64 Native Tools Command Prompt”, or after running vcvars64.bat. The VS Code extension sbt dixtraVsCode/vscodePackage builds the extension of dixtra-vscode/ (see The VS Code extension for what it does). Requirements: GRAALVM_HOME pointing to a GraalVM installation (GraalVM Community 25 or later); on Windows, the Visual Studio C++ build tools (the “Desktop development with C++” workload). If native-image doesn’t find them, start sbt from an “x64 Native Tools Command Prompt”, or after running vcvars64.bat. Everything it produces lands in dist/: dist/ ├── dixtra-vscode-&lt;version&gt;.vsix the extension, installable with code --install-extension ├── win32-x64/dixtra.exe the executable bundled with the extension └── linux-x64/dixtra built, but not bundled for now Install it with code --install-extension dist/dixtra-vscode-&lt;version&gt;.vsix or through the UI interface."
    } ,    
    {
      "title": "Call sites",
      "url": "/dixtra/docs/reference/call-site.html",
      "content": "Call sites The layout of the arguments where they are passed: calls, constructor calls and tuples. A trailing { ... } argument (foldLeft(z) { (acc, x) =&gt; ... }) is not a group, and follows its own rules. Every setting is in the settings table. call-site.trailing-commas Whether the last argument, or the last element of a tuple, of a list laid out one per line is followed by a comma. A list on one line never has one. Default call-site.trailing-commas = always. call-site.trailing-commas = always: compute( firstArgument, secondArgument, ) call-site.trailing-commas = never: compute( firstArgument, secondArgument ) call-site.groups-separator Where )( goes between the groups of arguments of a broken call. Default call-site.groups-separator = previous-group. call-site.groups-separator = previous-group — after the last argument of the group before, with the arguments of the next group below it: Resource.make( IO.blocking(Files.createTempFile(dir, prefix, \".tmp\")))( temp =&gt; IO.blocking(Files.delete(temp)).void, ) call-site.groups-separator = next-group — at the start of the next group, on the line of the closing ): Resource.make( IO.blocking(Files.createTempFile(dir, prefix, \".tmp\")), )(temp =&gt; IO.blocking(Files.delete(temp)).void, ) call-site.groups-break Which groups of arguments break when the groups of a call do not fit on one line. Default call-site.groups-break = last-first. call-site.groups-break = break-all — every group, each argument on its own line (see call-site.groups-separator above for the shape). call-site.groups-break = last-first — only the last group, while the groups before it fit on the line of the call; every group when they do not: Resource.make(IO.blocking(Files.createTempFile(dir, prefix, \".tmp\")))( temp =&gt; IO.blocking(Files.delete(temp)).void, ) call-site.groups-break = independent — each group by itself, as in a call with one group: a group breaks when the author broke it or it does not fit, and the others stay as they are: Resource.make( acquire, )(release) The settings Setting Default Values call-site.trailing-commas always always, never call-site.groups-separator previous-group previous-group, next-group call-site.groups-break last-first break-all, last-first, independent"
    } ,    
    {
      "title": "The command line",
      "url": "/dixtra/docs/command-line.html",
      "content": "The command line The command line is dixtra. It formats the files and the directories you give it, with the same formatter and the same configuration as the sbt plugin. dixtra [--config-string &lt;hocon&gt; | --config-path &lt;file&gt;] [--max-column &lt;n&gt;] [--check] [--changed-since &lt;ref&gt;] [--quiet] &lt;path&gt;... Options Option What it does &lt;path&gt;... Files and directories to format. At least one is required --check, -c Report the files that are not formatted, without writing them --max-column &lt;n&gt;, -w &lt;n&gt; The longest a line can be, over every max-column of the configuration --config-string &lt;hocon&gt; The configuration, as HOCON text, instead of the .dixtra.conf files --config-path &lt;file&gt; The configuration file to use, instead of the .dixtra.conf files --changed-since &lt;ref&gt; Only the files changed since a git ref --quiet, -q List only the files that change or fail, not the unchanged ones --version, -v Print the version --help Print the usage Exit codes Code When 0 Everything was formatted, or everything was already formatted 1 A file failed, or, in --check mode, a file would change 2 The options are invalid Examples Format the sources of a project: dixtra src Check that the sources are formatted, and fail when they are not: dixtra --check src Format only the files that changed since a branch: dixtra --changed-since origin/main src Format with a configuration that is not on the disk: dixtra --config-string \"max-column = 80, braces.style = allman\" src Format the build files of an sbt project: dixtra build.sbt project"
    } ,    
    {
      "title": "Configuration",
      "url": "/dixtra/docs/configuration.html",
      "content": "Configuration Dixtra gets its configuration from .dixtra.conf files, written in HOCON, the format of the reference configuration of the command line. config-version = 1.0.0 max-column = 100 braces { style = stroustrup, if = force-braces } paths.excluded = [\"**/generated/**\"] A project overrides only the settings it changes. Every setting that is not written keeps its default, listed with an example for every value in the settings reference. Which file applies For each file it formats, Dixtra uses the nearest .dixtra.conf in the directory of the file, or in a directory above it. Without one, it uses the defaults. The lookup stops at the first configuration found: a .dixtra.conf in a subdirectory does not inherit the one of the directory above it. Put the settings that apply to a whole project in the configuration of its root, and the ones that apply to a subtree in the configuration of that subtree. Replacing the configuration A file given with --config-path, or text given with --config-string, replaces the lookup: no .dixtra.conf is read at all. dixtra --config-string \"max-column = 80, braces.style = allman\" src dixtra --config-path build/.dixtra.conf src The same options exist in the sbt plugin, as dixtraConfig. The top-level settings Setting Default What it does config-version 1.0.0 The version of the schema of the configuration. A configuration without it is read as the current version; one written for a later version, or for another major version, is rejected instead of being half understood max-column 120 The longest a line can be. A construct whose one-line form does not fit within this width breaks compat213 false Whether the output must also be valid Scala 2.13, for the sources of a project cross-compiled for Scala 2.13 and Scala 3 Configuration version Dixtra follows Semantic versioning where given a version number MAJOR.MINOR.PATCH the: MAJOR version indicates incompatible API changes MINOR version indicates new functionalities in a backward compatible manner PATCH version indicates backward compatible bug fixes A configuration written for a another minor or path version of the same major version is guaranteed to be backward compatible. Column width This settings ensure that no line will exceed this width. Scala 2.13 compatibility compat213 keeps the output valid Scala 2.13 too, for the sources of a project cross-compiled for Scala 2.13 and Scala 3. When it is true, Dixtra enforces the settings that would otherwise write Scala 3 syntax, whatever the rest of the configuration says: Setting Value braces.&lt;construct&gt; keep, except package and try: force-braces braces.single-expr.&lt;construct&gt; keep body.semicolon-statements keep braces.style, braces.imports and the other body settings keep their values. A source that is valid Scala 2.13 too keeps the braces of the Scala 2 form, and a package clause and a try written without braces get them: def f = { a() b() } A source that is valid only in Scala 3 is still formatted, but the setting does not make it valid Scala 2.13. A source that is Scala 2 is still rejected. The setting can be set in a path-overrides entry, so only some files are formatted in compatibility mode. The settings reference The settings are split into one page per group. Each page lists the settings, their defaults and an example for every value they take. Group What it holds braces The braces, the end markers or the indentation of every construct, and where the braces go body Whether a body stays on the line of its separator, or goes below it selector-chain When a chain of selections breaks, and how alignment What lines up in columns blank-lines The blank lines at the edges of the bodies, between groups and before the scaladocs call-site The arguments of a call and the elements of a tuple: groups and commas definition-site The parameters of a def or of a class, and the selectors of an import: groups and commas overflow What happens to what goes past max-column housekeeping The trailing whitespace, the line break at the end of the file, the line endings paths The files of a directory to format path-overrides Other settings for some of the files Settings for some files path-overrides gives some files other settings. Each key is a glob, with the syntax of paths (*, **, ?), and its section holds the settings of the files it matches: path-overrides { \"src/main/scala/legacy/**\" { trailing-commas = never } \"build.sbt\" { housekeeping.enforce-eof = false } } Globs are relative to the directory of the configuration file that declares them, or to the working directory for --config-string. A file outside that directory never matches. A glob holding a . must be quoted, or HOCON reads the . as a section separator. Settings. A section can set any setting or alias but paths, config-version and path-overrides: those are ignored with a warning, as unknown settings are. Precedence. A file gets the settings of every glob its path matches, over the rest of the configuration: a setting in an override beats the same setting written outside path-overrides, directly or through an alias. Conflicts. Two matching globs that give a setting different values fail that file only, with the error &lt;setting&gt; is set to different values by path-overrides.\"&lt;glob&gt;\" and path-overrides.\"&lt;glob&gt;\". An invalid value in an override fails the whole configuration. The details of the globs are in path overrides. Ignoring the formatting The code between a dixtra: off comment and a dixtra: on comment stays exactly as written: object Matrices { val a = 1 // dixtra: off val identity = Array( 1, 0, 0, 1, ) // dixtra: on } Unclosed regions. Without a dixtra: on, the region runs to the end of the file. A // dixtra: off at the top of a file leaves the whole file as written. Nesting. An off inside a region, or an on outside one, does nothing. The markers themselves are laid out like any other comment. Only the code between them is protected. Disabling Dixtra for a subproject The dixtra: off markers protect regions of one file. To leave the sources and build files of a whole sbt subproject as written, turn the plugin off for that subproject: lazy val myProject = project .in(file(\"myProject\")) .disablePlugins(DixtraPlugin) The plugin then adds nothing to the subproject: its sources are not formatted on compile, and none of the dixtraFormat* or dixtraCheck* tasks run for it."
    } ,    
    {
      "title": "Definition sites",
      "url": "/dixtra/docs/reference/definition-site.html",
      "content": "Definition sites The layout of the names where they are declared: the parameters and the type parameters of defs and of class constructors, and the selectors of an import or of an export. A signature that does not fit breaks one parameter per line, and every group of parameters breaks with it. Every setting is in the settings table. definition-site.trailing-commas Whether the last parameter, type parameter or import selector of a list laid out one per line is followed by a comma. A list on one line never has one. Default definition-site.trailing-commas = always. definition-site.trailing-commas = always: def f( first: String, second: Boolean, ): Int = 1 definition-site.trailing-commas = never: def f( first: String, second: Boolean ): Int = 1 definition-site.groups-separator Where )( goes between the groups of parameters of a broken signature. Default definition-site.groups-separator = next-group. definition-site.groups-separator = next-group — at the start of the next group, on the line of the closing ): def f[A]( first: String, second: Boolean, )(numeric: Numeric[A], )(using ord: Ordering[A], ): Int = 1 definition-site.groups-separator = previous-group — after the last parameter of the group before, with the parameters of the next group below it: def f[A]( first: String, second: Boolean)( numeric: Numeric[A])( using ord: Ordering[A], ): Int = 1 A using or an implicit keyword is placed like a parameter: on a line of its own when its group opens at the end of a line, and on the )( line with definition-site.groups-separator = next-group. The settings Setting Default Values definition-site.trailing-commas always always, never definition-site.groups-separator next-group next-group, previous-group"
    } ,    
    {
      "title": "Housekeeping",
      "url": "/dixtra/docs/reference/housekeeping.html",
      "content": "Housekeeping The housekeeping of a whole file, applied after the other formatting. Every setting is in the settings table. housekeeping.trim-trailing-whitespace Whether the spaces and the tabs at the end of each line are removed. Default housekeeping.trim-trailing-whitespace = true. housekeeping.trim-trailing-whitespace = true — removed: val a = 1 housekeeping.trim-trailing-whitespace = false — kept, though the layout of comments still trims the end of a comment. housekeeping.enforce-eof Whether the file ends with exactly one line break (standard Unix EOF). Default housekeeping.enforce-eof = true. housekeeping.enforce-eof = true — a missing line break at the end of the file is added, and the blank lines at its end are removed. housekeeping.enforce-eof = false — the end of the file stays as written. housekeeping.line-ending The line break written at the end of each line, string literals over several lines included. Default housekeeping.line-ending = keep. housekeeping.line-ending = lf — \\n, as on Linux and macOS. housekeeping.line-ending = crlf — \\r\\n, as on Windows. housekeeping.line-ending = cr — \\r, as on classic macOS (up to Mac OS 9). housekeeping.line-ending = keep — the line break of the file as it is written. The settings Setting Default Values housekeeping.trim-trailing-whitespace true true, false housekeeping.enforce-eof true true, false housekeeping.line-ending keep lf, crlf, cr, keep"
    } ,    
    {
      "title": "Intro",
      "url": "/dixtra/docs/",
      "content": "Introduction Dixtra is an opinionated formatter for Scala 3. Its primary goal is visual consistency and clarity across constructs. Other Scala formatters let you tune typographic details: where the parentheses go, how the indentation works, when a comma is written. Dixtra treats the code as having visual features that must be formatted as a unit, and gives you fewer settings, so that the result is consistent by construction. Design Principles These are the principles used to develop and design Dixtra: Format visual features Dixtra targers visual features for formattings: alignment blocks blank lines bodies braces call site definition site selector chain and as such they are formatted as a unit. For example, a definition site with multiple parameter groups will uniformly format the parameters. Consistency across formattings The same visual feature must format the same, everywhere in the code. For example, if a selector chain breaks after 3 selectors, it always does so. One concept per line Strongly favour having one “concept” per line. This can be a selector chain, the name of a function, a member, a parameter and more. Scala allows so much flexibility that the code can become easily unreadable. Optinionated Ultimately, this is a personal project aimed at solving long standing frustrations with the existing formatters and, as such, it strongly favours my views on stlyling. Three ways to use it The sbt plugin, for a project that builds with sbt 2. The command line, dixtra, for any project, and for the files that are not part of a build. The VS Code extension, to format the file that is open in the editor. All three run the same formatter, with the same configuration. Where to go next Setup: install Dixtra and format something. Using Dixtra: format, check, and format only what changed. Configuration: the .dixtra.conf file, and the settings reference with an example for every value. Rules and limitations: the rules that have no setting, and what Dixtra cannot parse yet. Building from source: build the formatter, the command line, the sbt plugin and the VS Code extension."
    } ,      
    {
      "title": "Using Dixtra as a library",
      "url": "/dixtra/docs/library.html",
      "content": "Using Dixtra as a library dixtra-core is the formatter alone, with no dependency other than scalameta: libraryDependencies += \"com.colofabrix.scala\" %% \"dixtra-core\" % \"1.0.0-RC1\" import com.colofabrix.scala.dixtra.{ Config, Dixtra, SourceDialect } Dixtra.format(source) // the default configuration Dixtra.format(source, Config.default.copy(maxColumn = 100)) Dixtra.format(source, Config.default, SourceDialect.sbt) // an sbt 2 build file Dixtra.format is a pure function from text to text. It returns Right(formatted), or Left of a FormatError: ParseError: the source is not valid Scala 3; Scala2Error: the source is Scala 2; UnsafeOutputError: the output would not be equivalent to the input. This signals a formatter bug, not a problem with the source. Embedded.run in dixtra-cli runs the command line without exiting the JVM, with Java types only: it hands each report line to a callback, one for the standard output and one for the standard error, and returns the exit code, 2 for invalid options. The sbt plugin calls it from its own class loader. The API is documented in the API documentation."
    } ,      
    {
      "title": "Overflow",
      "url": "/dixtra/docs/reference/overflow.html",
      "content": "Overflow What happens to what goes past max-column, when breaking the construct is not the answer. overflow.trailing-comment What happens to a line that goes past max-column only because of the comment at its end. Default overflow.trailing-comment = keep. overflow.trailing-comment = keep — the line stays longer than max-column: val total = prices.sum // a comment that does not fit overflow.trailing-comment = move-above — the comment moves to a line of its own above the code, at its indent, wrapped if it is too long: // a comment that does not fit val total = prices.sum A trailing comment never counts in the width, so the code before it never breaks because of it. The settings Setting Default Values overflow.trailing-comment keep keep, move-above"
    } ,    
    {
      "title": "Path overrides",
      "url": "/dixtra/docs/reference/path-overrides.html",
      "content": "Path overrides Other settings for some of the files. The default is path-overrides {}: no file gets other settings. Each key is a glob, as those of paths, relative to the directory of the configuration file that declares it, or to the working directory for --config-string. Its section sets any setting or alias, except paths, config-version and path-overrides: those are ignored with a warning, as unknown settings are. path-overrides { \"path/to/file_1\" { call-site.trailing-commas = never } \"path/to/other/file_2.scala\" { housekeeping.enforce-eof = false } \"path/that/uses/**/globs/*\" { housekeeping.line-ending = lf } } The rules Globs are relative to the directory of the configuration file that declares them. A file outside that directory never matches. A glob holding a . must be quoted, or HOCON reads the . as a section separator. Precedence. A file gets the settings of every glob its path matches, over the rest of the configuration: a setting in an override beats the same setting written outside path-overrides, directly or through an alias. Conflicts. Two matching globs that give a setting different values fail that file only, with the error &lt;setting&gt; is set to different values by path-overrides.\"&lt;glob&gt;\" and path-overrides.\"&lt;glob&gt;\". An invalid value in an override fails the whole configuration. An example A project formats the legacy sources without trailing commas and with the braces of a def forced, while the rest of the project keeps the defaults: path-overrides { \"src/main/scala/legacy/**\" { call-site.trailing-commas = never braces.def = force-braces } }"
    } ,    
    {
      "title": "Paths",
      "url": "/dixtra/docs/reference/paths.html",
      "content": "Paths The files to format inside the directories given to Dixtra. Every setting is in the settings table. The patterns are globs relative to the directory being formatted, with / between directories: * matches within a directory name, ** across directories, ? matches one character. A file is formatted when it matches a paths.included pattern and neither it nor a directory above it matches a paths.excluded pattern. The hidden directories (.git, .metals, …) and the target directories are always skipped, and a file given explicitly is always formatted. paths.included The files to format. Default paths.included = [\"**\"]. paths.excluded The files and the directories to skip among the included ones. Default paths.excluded = []. Both hold lists of globs: paths { included = [\"src/**\"] excluded = [\"**/generated/**\", \"legacy/*.scala\"] } With that configuration, only the files below src are formatted, and the directories named generated and the Scala files directly in legacy are skipped. The settings Setting Default Values paths.included [\"**\"] a list of globs paths.excluded [] a list of globs"
    } ,    
    {
      "title": "Rules and limitations",
      "url": "/dixtra/docs/rules.html",
      "content": "Rules and limitations Rules that have no setting Some rules are fixed, on purpose: they are part of what makes the result consistent. Indentation is 2 spaces. Spaces. A run of spaces between two tokens on a line becomes one, except where Dixtra aligns code. Blank lines. A run of blank lines becomes one. Braces. Only few braces styles are allowed. When Dixtra has no rule for a specific code snippet, the code is copied exactly as written. Known limitations Among the Scala 3 syntax it does not parse yet is into on a type (Scala 3.9). When Dixtra cannot format a file A file is reported, and left as it is, when: it is not valid Scala 3, or it is Scala 2: Dixtra rejects it with the error of the parser; it holds a construct that Dixtra does not parse yet; the formatted result would not be equivalent to the input, which signals a bug in the formatter: the file is left untouched and the error is reported."
    } ,    
    {
      "title": "The sbt plugin",
      "url": "/dixtra/docs/sbt-plugin.html",
      "content": "The sbt plugin The plugin requires sbt 2, and runs against Scala 3 code. // project/plugins.sbt addSbtPlugin(\"com.colofabrix.scala\" % \"sbt-dixtra\" % \"$VERSION\") Tasks Task What it does dixtraFormat Formats the sources of a configuration (Compile; Test / dixtraFormat for the tests) dixtraCheck Fails when a source of a configuration is not formatted dixtraFormatAll Formats the sources of Compile and Test, and the build files dixtraCheckAll Fails when a source of Compile or Test, or a build file, is not formatted dixtraFormatSbt Formats the build: the .sbt files, and the .sbt / .scala files in project/ dixtraCheckSbt Fails when a file of the build is not formatted dixtraFormatOnly &lt;files&gt; Formats the given files, relative to the project directory dixtraClasspath The jars of dixtra-cli and its dependencies, as resolved for dixtraVersion The tasks cover the unmanaged source directories of a configuration, so the generated sources are left alone. Settings Setting Default What it does dixtraVersion the plugin version The version of Dixtra to format with dixtraConfig None A configuration file, instead of the nearest .dixtra.conf dixtraChangedSince None A git ref: format or check only the files changed since it dixtraOnCompile false Format the sources of a configuration before compiling them // build.sbt dixtraOnCompile := true dixtraChangedSince := Some(\"origin/main\") In a CI job The check tasks fail the build when a file is not formatted, which is what a CI job wants: sbt dixtraCheckAll Only the files that changed Formatting a whole project on every save is wasteful when only a few files changed. Both the plugin and the command line can restrict the work to the files that changed since a git ref: // build.sbt dixtraChangedSince := Some(\"origin/main\") dixtra --changed-since origin/main src A file counts as changed when it was committed since the ref, has uncommitted changes, or is new and not ignored by git. With HEAD, only the uncommitted changes count."
    } ,      
    {
      "title": "Selector chains",
      "url": "/dixtra/docs/reference/selector-chain.html",
      "content": "Selector chains When a chain of selections (a.b(x).c.d) breaks, one selection per line. A chain always breaks when it does not fit, or when the author broke it before a dot. A broken chain has its receiver on the first line and each selection below it, one level in: xs .filter(_.paid) .map(_.amount) .sum A receiver that the formatter expands over several lines ends with its closing parenthesis on a line of its own, and the selections then line up with that parenthesis instead of going one level further in: val candidates = Seq( sys.env.get(\"ProgramFiles(x86)\"), sys.env.get(\"ProgramFiles\"), ) .flatten .map(file(_) / \"vswhere.exe\") Every setting is in the settings table. selector-chain.inline-chains Whether a chain on the line of its = or =&gt; breaks at selector-chain.break-at-count selections too. Default selector-chain.inline-chains = break-at-count. selector-chain.inline-chains = break-at-count — it breaks like a chain written below the =, and goes below it: val y = xs .map(_ + 1) .filter(_ &gt; 0) .sum selector-chain.inline-chains = keep — it stays on one line while it fits: val y = xs.map(_ + 1).filter(_ &gt; 0).sum selector-chain.break-at-count How many selections make a chain that is a whole body break, even when it fits. Default selector-chain.break-at-count = 3. The receiver does not count, and the value is at least 2. With selector-chain.break-at-count = 3, two selections stay on one line and three break: def total = xs.map(_.amount).sum def total = xs .filter(_.paid) .map(_.amount) .sum A chain inside an operation, an argument or a condition breaks only when it does not fit, or when the author broke it: p.speed.vertical &gt;= config.minSpeed stays on one line. A chain on the line of its = follows selector-chain.inline-chains. selector-chain.in-for How a chain breaks in the enumerators of a for: the generators (x &lt;- xs), the guards (if ...) and the value definitions (y = ...), and everything they hold. The expression after yield and the body after do are not enumerators. A chain there never breaks at selector-chain.break-at-count selections, and it always breaks when it does not fit. Default selector-chain.in-for = never-break. selector-chain.in-for = never-break — a chain the author broke is joined while it fits: for user &lt;- users.filter(_.active) yield user.name selector-chain.in-for = keep — a chain stays broken where the author broke it: for user &lt;- users .filter(_.active) yield user.name selector-chain.in-call How a chain breaks in the arguments of a call: the arguments of a call or of a constructor, positional or named, the elements of a tuple, the arguments of an infix application with several of them (x shouldBe (a, b)), and everything they hold. The bodies of the lambdas and of the blocks given as arguments are not arguments: a chain there breaks like in any other body. A chain in an argument never breaks at selector-chain.break-at-count selections, and it always breaks when it does not fit. Default selector-chain.in-call = never-break. selector-chain.in-call = never-break — a chain the author broke is joined while it fits: SignatureParts( nameEnd = d.name.pos.end, ) selector-chain.in-call = keep — a chain stays broken where the author broke it: SignatureParts( nameEnd = d .name .pos .end, ) selector-chain.namespace-path Whether a package path at the start of a chain stays together as its receiver. A package path is the run of lowercase names up to the first capitalised one: java.nio.file.Files. Default selector-chain.namespace-path = keep. selector-chain.namespace-path = always-join — always, even when the author broke the line inside the path: java.nio.file.Files .exists(path) .toString selector-chain.namespace-path = keep — as selector-chain.namespace-path = always-join, unless the author broke the line inside the path. selector-chain.namespace-path = always-break — the path breaks like any other selection: java .nio .file .Files .exists(path) .toString selector-chain.object-member Whether the first member selected on a capitalised name stays with it as the receiver. Default selector-chain.object-member = always-break. selector-chain.object-member = always-join — always, even when the author broke the line before its dot: IO.pure(x) .map(f) .flatMap(g) selector-chain.object-member = keep — as selector-chain.object-member = always-join, unless the author broke the line before its dot. selector-chain.object-member = always-break — the member breaks like any other selection: IO .pure(x) .map(f) .flatMap(g) selector-chain.receiver-min-length The shortest receiver name a chain breaks after. Default selector-chain.receiver-min-length = 1, and the value is at least 1. A shorter receiver keeps its first selection on its line, and that selection still counts towards selector-chain.break-at-count. With selector-chain.receiver-min-length = 3, v keeps .trim and values breaks: v.trim .toLowerCase .nonEmpty values .map(_.trim) .filter(_.nonEmpty) .size The settings Setting Default Values selector-chain.inline-chains break-at-count break-at-count, keep selector-chain.break-at-count 3 a number, at least 2 selector-chain.in-for never-break never-break, keep selector-chain.in-call never-break never-break, keep selector-chain.namespace-path keep always-join, keep, always-break selector-chain.object-member always-break always-join, keep, always-break selector-chain.receiver-min-length 1 a number, at least 1"
    } ,    
    {
      "title": "Setup",
      "url": "/dixtra/docs/usage.html",
      "content": "Setup Requirements Dixtra runs against Scala 3 code and it supports Scala 2.13 output for cross-compiled projects. The plugin requires sbt 2. The sbt plugin Add the plugin to project/plugins.sbt: addSbtPlugin(\"com.colofabrix.scala\" % \"sbt-dixtra\" % \"1.0.0-RC1\") The plugin is enabled in every project of the build. Its tasks are listed in the sbt plugin. With the plugin installed, format the sources of a project: sbt dixtraFormatAll and check that they are formatted: sbt dixtraCheckAll Dixtra formats the code it understands and copies the rest, so the first run rarely fails: it reports the files it could not format, and the ones it could not parse. The VS Code extension The extension formats the document of the editor with Dixtra when you run Format Document (Shift+Alt+F). Install it with code --install-extension dixtra-vscode-&lt;platform&gt;-&lt;version&gt;.vsix, from the releases page, or from the VS Code marketplace when it is published there. It is described in the VS Code extension. The command line The command line is a single executable, dixtra. It formats the files you give it, whatever they are, and it is the same formatter the plugin and the extension use. Download the executable for your platform from the releases page, and put it on your path: linux-x64 dixtra-linux-x64 macos-arm64 dixtra-darwin-arm64 windows-x64 dixtra-win32-x64.exe Then format a directory: dixtra src The options are listed in the command line. The library The formatter alone, with no dependency other than scalameta: libraryDependencies += \"com.colofabrix.scala\" %% \"dixtra-core\" % \"1.0.0-RC1\" Its API is described in using Dixtra as a library."
    } ,    
    {
      "title": "The VS Code extension",
      "url": "/dixtra/docs/vscode.html",
      "content": "The VS Code extension The extension formats the document of the editor with Dixtra when you run Format Document (Shift+Alt+F). A document with unsaved changes is saved first, and Dixtra runs on the file on disk, so the nearest .dixtra.conf and its path-overrides apply as in the command line. Install code --install-extension dixtra-vscode-&lt;platform&gt;-&lt;version&gt;.vsix The releases page holds one package per platform: dixtra-vscode-linux-x64-&lt;version&gt;.vsix, dixtra-vscode-win32-x64-&lt;version&gt;.vsix and dixtra-vscode-darwin-arm64-&lt;version&gt;.vsix. The extension bundles the Dixtra executable, so no PATH setup is needed. When VS Code asks, pick Dixtra as the default formatter for the Scala files. Settings Setting Default What it does dixtra.executablePath empty The Dixtra executable to format with. Empty uses the bundled one, or dixtra from the PATH dixtra.arguments [] Extra arguments, e.g. [\"--max-column\", \"100\"] { \"dixtra.arguments\": [\"--max-column\", \"100\"] }"
    }    
  ];

  idx = lunr(function () {
    this.ref("title");
    this.field("content");

    docs.forEach(function (doc) {
      this.add(doc);
    }, this);
  });

  docs.forEach(function (doc) {
    docMap.set(doc.title, doc.url);
  });
}

// The onkeypress handler for search functionality
function searchOnKeyDown(e) {
  const keyCode = e.keyCode;
  const parent = e.target.parentElement;
  const isSearchBar = e.target.id === "search-bar";
  const isSearchResult = parent ? parent.id.startsWith("result-") : false;
  const isSearchBarOrResult = isSearchBar || isSearchResult;

  if (keyCode === 40 && isSearchBarOrResult) {
    // On 'down', try to navigate down the search results
    e.preventDefault();
    e.stopPropagation();
    selectDown(e);
  } else if (keyCode === 38 && isSearchBarOrResult) {
    // On 'up', try to navigate up the search results
    e.preventDefault();
    e.stopPropagation();
    selectUp(e);
  } else if (keyCode === 27 && isSearchBarOrResult) {
    // On 'ESC', close the search dropdown
    e.preventDefault();
    e.stopPropagation();
    closeDropdownSearch(e);
  }
}

// Search is only done on key-up so that the search terms are properly propagated
function searchOnKeyUp(e) {
  // Filter out up, down, esc keys
  const keyCode = e.keyCode;
  const cannotBe = [40, 38, 27];
  const isSearchBar = e.target.id === "search-bar";
  const keyIsNotWrong = !cannotBe.includes(keyCode);
  if (isSearchBar && keyIsNotWrong) {
    // Try to run a search
    runSearch(e);
  }
}

// Move the cursor up the search list
function selectUp(e) {
  if (e.target.parentElement.id.startsWith("result-")) {
    const index = parseInt(e.target.parentElement.id.substring(7));
    if (!isNaN(index) && (index > 0)) {
      const nextIndexStr = "result-" + (index - 1);
      const querySel = "li[id$='" + nextIndexStr + "'";
      const nextResult = document.querySelector(querySel);
      if (nextResult) {
        nextResult.firstChild.focus();
      }
    }
  }
}

// Move the cursor down the search list
function selectDown(e) {
  if (e.target.id === "search-bar") {
    const firstResult = document.querySelector("li[id$='result-0']");
    if (firstResult) {
      firstResult.firstChild.focus();
    }
  } else if (e.target.parentElement.id.startsWith("result-")) {
    const index = parseInt(e.target.parentElement.id.substring(7));
    if (!isNaN(index)) {
      const nextIndexStr = "result-" + (index + 1);
      const querySel = "li[id$='" + nextIndexStr + "'";
      const nextResult = document.querySelector(querySel);
      if (nextResult) {
        nextResult.firstChild.focus();
      }
    }
  }
}

// Search for whatever the user has typed so far
function runSearch(e) {
  if (e.target.value === "") {
    // On empty string, remove all search results
    // Otherwise this may show all results as everything is a "match"
    applySearchResults([]);
  } else {
    const tokens = e.target.value.split(" ");
    const moddedTokens = tokens.map(function (token) {
      // "*" + token + "*"
      return token;
    })
    const searchTerm = moddedTokens.join(" ");
    const searchResults = idx.search(searchTerm);
    const mapResults = searchResults.map(function (result) {
      const resultUrl = docMap.get(result.ref);
      return { name: result.ref, url: resultUrl };
    })

    applySearchResults(mapResults);
  }

}

// After a search, modify the search dropdown to contain the search results
function applySearchResults(results) {
  const dropdown = document.querySelector("div[id$='search-dropdown'] > .dropdown-content.show");
  if (dropdown) {
    //Remove each child
    while (dropdown.firstChild) {
      dropdown.removeChild(dropdown.firstChild);
    }

    //Add each result as an element in the list
    results.forEach(function (result, i) {
      const elem = document.createElement("li");
      elem.setAttribute("class", "dropdown-item");
      elem.setAttribute("id", "result-" + i);

      const elemLink = document.createElement("a");
      elemLink.setAttribute("title", result.name);
      elemLink.setAttribute("href", result.url);
      elemLink.setAttribute("class", "dropdown-item-link");

      const elemLinkText = document.createElement("span");
      elemLinkText.setAttribute("class", "dropdown-item-link-text");
      elemLinkText.innerHTML = result.name;

      elemLink.appendChild(elemLinkText);
      elem.appendChild(elemLink);
      dropdown.appendChild(elem);
    });
  }
}

// Close the dropdown if the user clicks (only) outside of it
function closeDropdownSearch(e) {
  // Check if where we're clicking is the search dropdown
  if (e.target.id !== "search-bar") {
    const dropdown = document.querySelector("div[id$='search-dropdown'] > .dropdown-content.show");
    if (dropdown) {
      dropdown.classList.remove("show");
      document.documentElement.removeEventListener("click", closeDropdownSearch);
    }
  }
}
